use std::path::Path;

fn main() {
  // The Typst engine is embedded from engine/ (generated by `npm run engine:sync`)
  let engine = Path::new("../engine");
  if !engine.join("bundle/main.typ").exists() || !engine.join("config.toml").exists() {
    panic!("engine/ is missing: run `npm run engine:sync` in the app folder first");
  }
  println!("cargo:rerun-if-changed=../engine");

  tauri_build::build()
}
